fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    if min_val <= max_val {
        arr.iter()
            .map(|&x| {
                if x < min_val {
                    min_val
                } else if x > max_val {
                    max_val
                } else {
                    x
                }
            })
            .collect()
    } else {
        // If the lower bound is greater than the upper bound, fill with max_val
        vec![max_val; arr.len()]
    }
}

