    #[test]
    fn test_clip_with_valid_bounds() {
        let input = vec![-10, -5, 0, 5, 10];
        assert_eq!(clip(&input, -5, 5), vec![-5, -5, 0, 5, 5]);
        assert_eq!(clip(&input, 0, 0), vec![0, 0, 0, 0, 0]);
        assert_eq!(clip(&input, -20, 20), input);
    }

    #[test]
    fn test_clip_with_invalid_bounds() {
        let input = vec![-10, 0, 10];
        // min_val > max_val, so all entries become max_val
        assert_eq!(clip(&input, 5, -5), vec![-5, -5, -5]);
        assert_eq!(clip(&input, 100, -100), vec![-100, -100, -100]);
    }

    #[test]
    fn test_empty_input() {
        let input: Vec<i8> = vec![];
        assert!(clip(&input, -5, 5).is_empty());
        assert!(clip(&input, 5, -5).is_empty());
    }
